const billingTransaction=<T>(request:Request,permission:BillingPermission,work:(connection:PoolConnection)=>Promise<T>)=>withCurrentAgencyAuthorizationRetry(request,async(connection,context)=>{const scope=context.permissions.get(permission);if(!scope||scope==='OWN')throw new HttpError(403,'Périmètre financier insuffisant.');return work(connection)});
const id=(v:unknown)=>{const x=String(v??'');if(!/^[1-9]\d*$/.test(x))throw new HttpError(400,'Identifiant invalide');return x};
const oid=(v:unknown)=>v==null||v===''?null:id(v);
const txt=(v:unknown,n=2000)=>String(v??'').trim().slice(0,n);
const money=(v:unknown,label:string,min=0)=>{const x=Number(v);if(!Number.isFinite(x)||x<min)throw new HttpError(400,`${label} invalide`);return Math.round(x*100)/100};
function date(v:unknown,label:string,required:true):string;
function date(v:unknown,label:string,required?:false):string|null;
function date(v:unknown,label:string,required=false){const x=txt(v,10);if(!x&&!required)return null;if(!/^\d{4}-\d{2}-\d{2}$/.test(x))throw new HttpError(400,`${label} invalide`);const d=new Date(`${x}T00:00:00Z`);if(Number.isNaN(d.getTime())||d.toISOString().slice(0,10)!==x)throw new HttpError(400,`${label} invalide`);return x}
const grant=(r:Request,p:BillingPermission)=>r.agencyRbac?.permissions.get(p);
export function billingScopeSql(r:Request,p:BillingPermission,column='i.agency_id'){
  const scope=grant(r,p),agencyId=r.agencyRbac?.activeAgencyId;
  if(!scope)throw new HttpError(403,'Permission financière insuffisante.');
  if(!agencyId)throw new HttpError(403,'Aucune agence associée');
  if(scope==='OWN')throw new HttpError(403,'Le scope OWN n’est pas applicable aux données financières sans propriétaire métier.');
  return{sql:`${column}=?`,params:[agencyId]};
}
const targetAgency=(r:Request,p:BillingPermission,_v:unknown=r.query.agencyId??r.body?.agencyId)=>{const scope=grant(r,p);if(!scope||scope==='OWN')throw new HttpError(403,'Le scope OWN n’est pas applicable aux données financières.');return id(r.agencyRbac?.activeAgencyId)};
async function billingExportAgency(r:Request){const scope=grant(r,'billing.export'),actorAgency=id(r.agencyRbac?.activeAgencyId),requested=r.query.agencyId==null||r.query.agencyId===''?actorAgency:id(r.query.agencyId);if(scope==='OWN'||!scope)throw new HttpError(403,'Périmètre financier insuffisant.');if(requested!==actorAgency)throw new HttpError(403,'Agence hors du périmètre d’export.');const allowed=await query<RowDataPacket[]>('SELECT id FROM agencies WHERE id=? AND is_active=TRUE',[actorAgency]);if(!allowed[0])throw new HttpError(403,'Agence hors du périmètre d’export.');return actorAgency}
const invoiceFrom=`FROM invoices i JOIN customers c ON c.id=i.customer_id JOIN agencies a ON a.id=i.agency_id LEFT JOIN sales s ON s.id=i.sale_id LEFT JOIN repair_orders ro ON ro.id=i.repair_order_id`;
const base=`SELECT i.*,CASE WHEN i.balance_due>0 AND i.due_date<CURDATE() AND i.status NOT IN('paid','cancelled') THEN 'overdue' ELSE i.status END effective_status,COALESCE(c.company_name,CONCAT_WS(' ',c.first_name,c.last_name)) customer_name,c.email customer_email,c.phone customer_phone,c.address customer_address,a.name agency_name,a.code agency_code,a.address agency_address,s.sale_number,s.deposit_amount legacy_sale_deposit,ro.order_number repair_order_number ${invoiceFrom}`;
async function access(invoiceId:string,r:Request,p:BillingPermission,c?:PoolConnection,lock=false){const scoped=billingScopeSql(r,p),sql=`${base} WHERE i.id=? AND ${scoped.sql}${lock?' FOR UPDATE':''}`,params=[invoiceId,...scoped.params] as any[];const rows=c?(await c.execute<RowDataPacket[]>(sql,params))[0]:await query<RowDataPacket[]>(sql,params);if(!rows[0])throw new HttpError(404,'Facture introuvable');return rows[0]}
async function audit(c:PoolConnection,r:Request,entity:string,entityId:string,action:string,values:unknown){await writeAudit(c,r,{module:'billing',entityType:entity,entityId,action,newValues:values})}
function lines(raw:unknown,taxMode:TaxMode,priceInputMode:PriceInputMode,taxRate:number){if(!Array.isArray(raw)||!raw.length)throw new HttpError(400,'La facture doit contenir au moins une ligne');return raw.map((x:any)=>{const description=txt(x.description,255);if(!description)throw new HttpError(400,'Description de ligne obligatoire');const result=calculateTaxLine({quantity:x.quantity,unitPrice:x.unitPrice,discount:x.discount??0,taxMode,priceInputMode,taxRate});return{...result,description,unitPrice:result.unitPriceHt,discount:result.discountHt,total:result.totalTtc,vehicleId:oid(x.vehicleId),partId:oid(x.partId)}})}
const totals=(items:ReturnType<typeof lines>)=>{const result=aggregateTaxLines(items);if(result.total<=0)throw new HttpError(400,'Le total de la facture doit être strictement positif');return result};
async function insertLines(c:PoolConnection,invoiceId:string,items:ReturnType<typeof lines>){for(const x of items)await c.execute('INSERT INTO invoice_items(invoice_id,vehicle_id,part_id,description,quantity,unit_price,discount,tax_rate,tax_amount,line_total) VALUES(?,?,?,?,?,?,?,?,?,?)',[invoiceId,x.vehicleId,x.partId,x.description,x.quantity,x.unitPrice,x.discount,x.taxRate,x.tax,x.total])}
export async function recalculateInvoice(c:PoolConnection,invoiceId:string){const[rows]=await c.execute<RowDataPacket[]>(`SELECT i.total,i.sale_id,i.invoice_type,COALESCE(SUM(CASE WHEN p.status='confirmed' AND NOT EXISTS(SELECT 1 FROM payment_cancellations pc WHERE pc.payment_id=p.id) THEN p.amount ELSE 0 END),0)-(SELECT COALESCE(SUM(pr.amount),0) FROM payment_refunds pr WHERE pr.invoice_id=i.id) paid,(SELECT COALESCE(SUM(amount),0) FROM credit_notes WHERE invoice_id=i.id AND status IN('issued','applied')) credited FROM invoices i LEFT JOIN payments p ON p.invoice_id=i.id WHERE i.id=? GROUP BY i.id`,[invoiceId]);const x=rows[0];if(!x)throw new HttpError(404,'Facture introuvable');const paid=Math.max(0,Number(x.paid)),net=Math.max(0,Number(x.total)-Number(x.credited)),balance=Math.max(0,net-paid),status=balance<=.001?'paid':paid>0?'partially_paid':'issued';await c.execute('UPDATE invoices SET amount_paid=?,balance_due=?,status=? WHERE id=?',[paid,balance,status,invoiceId]);if(x.sale_id&&x.invoice_type==='vehicle')await c.execute('UPDATE sales SET deposit_amount=?,balance_due=? WHERE id=?',[paid,balance,x.sale_id]);return{paid,balance,status}}
const recalc=recalculateInvoice;
const notifyAccounting=(agencyId:string,actorUserId:string,subject:string,message:string,referenceType:'invoice'|'payment',referenceId:string,eventType:string,eventKey:string)=>notifyPermissions({agencyId,permissions:['billing.payment.view'],subject,message,eventType,referenceType,referenceId,eventKey,priority:'normal',actorType:'human',actorUserId});

