 const exportAgencyId=await billingExportAgency(r),scoped={sql:'i.agency_id=?',params:[exportAgencyId]},from=date(r.query.from,'Date début'),to=date(r.query.to,'Date fin'),config=await getEffectiveBusinessSettings(exportAgencyId);
 const invoices=await query<RowDataPacket[]>(`${base} WHERE ${scoped.sql} AND (? IS NULL OR i.issue_date>=?) AND (? IS NULL OR i.issue_date<=?)`,[...scoped.params,from,from,to,to]);
 const payments=await query<RowDataPacket[]>(`SELECT p.payment_number,p.payment_date,p.amount,p.status,pm.name payment_method,i.invoice_number FROM payments p JOIN invoices i ON i.id=p.invoice_id JOIN payment_methods pm ON pm.id=p.payment_method_id WHERE ${scoped.sql} AND p.status IN('confirmed','refunded') AND (? IS NULL OR DATE(p.payment_date)>=?) AND (? IS NULL OR DATE(p.payment_date)<=?)`,[...scoped.params,from,from,to,to]);
