billingRouter.post('/payments/:id/refund',requirePermission('billing.payment.refund'),asyncHandler(async(r,res)=>{const paymentId=id(r.params.id),creditNoteId=id(r.body.creditNoteId),amount=money(r.body.amount,'Montant remboursement',.01),reason=txt(r.body.reason,500),key=txt(r.body.idempotencyKey,120);if(!reason||!key)throw new HttpError(400,'Motif et clé d’idempotence du remboursement requis');const targets=await query<RowDataPacket[]>('SELECT p.invoice_id,i.sale_id FROM payments p JOIN invoices i ON i.id=p.invoice_id WHERE p.id=?',[paymentId]),target=targets[0];if(!target)throw new HttpError(404,'Paiement introuvable');await access(String(target.invoice_id),r,'billing.payment.refund');const result=await billingTransaction(r,'billing.payment.refund',async c=>{if(target.sale_id){const[sales]=await c.execute<RowDataPacket[]>('SELECT id FROM sales WHERE id=? FOR UPDATE',[target.sale_id]);if(!sales[0])throw new HttpError(409,'Vente associée introuvable')}const invoice=await access(String(target.invoice_id),r,'billing.payment.refund',c,true);const[dupe]=await c.execute<RowDataPacket[]>('SELECT id,payment_id,invoice_id,credit_note_id,amount FROM payment_refunds WHERE idempotency_key=? FOR UPDATE',[key]);if(dupe[0]){if(String(dupe[0].payment_id)!==paymentId||String(dupe[0].credit_note_id)!==creditNoteId||Number(dupe[0].amount)!==amount)throw new HttpError(409,'Cette clé d’idempotence appartient à un autre remboursement');return{id:String(dupe[0].id),invoiceId:String(dupe[0].invoice_id),agencyId:String(invoice.agency_id),duplicate:true,treasuryAgencies:[]as string[]}}const[credits]=await c.execute<RowDataPacket[]>(`SELECT cn.*,COALESCE((SELECT SUM(pr.amount) FROM payment_refunds pr WHERE pr.credit_note_id=cn.id),0) refunded_amount FROM credit_notes cn WHERE cn.id=? FOR UPDATE`,[creditNoteId]),credit=credits[0];if(!credit||String(credit.invoice_id)!==String(invoice.id)||!['issued','applied'].includes(String(credit.status)))throw new HttpError(409,'Avoir incompatible ou non applicable');const[payments]=await c.execute<RowDataPacket[]>(`SELECT p.*,COALESCE((SELECT SUM(pr.amount) FROM payment_refunds pr WHERE pr.payment_id=p.id),0) refunded_amount FROM payments p WHERE p.id=? FOR UPDATE`,[paymentId]),payment=payments[0];if(!payment||String(payment.invoice_id)!==String(invoice.id)||payment.status!=='confirmed')throw new HttpError(409,'Paiement incompatible ou non remboursable');const paymentRemaining=Number(payment.amount)-Number(payment.refunded_amount),creditRemaining=Number(credit.amount)-Number(credit.refunded_amount);if(amount>paymentRemaining+.001)throw new HttpError(409,'Remboursement supérieur au reliquat du paiement');if(amount>creditRemaining+.001)throw new HttpError(409,"Remboursement supérieur au reliquat de l’avoir");const[created]=await c.execute<ResultSetHeader>('INSERT INTO payment_refunds(payment_id,invoice_id,credit_note_id,amount,reason,refunded_by,idempotency_key) VALUES(?,?,?,?,?,?,?)',[paymentId,invoice.id,creditNoteId,amount,reason,r.user!.sub,key]),[posted]=await c.execute<RowDataPacket[]>('SELECT DATE(refunded_at) value_date FROM payment_refunds WHERE id=?',[created.insertId]),treasury=await postPaymentRefundMovement(c,{agencyId:String(invoice.agency_id),paymentMethodId:String(payment.payment_method_id),direction:'OUT',amount,currencyCode:String(invoice.currency_code),valueDate:String(posted[0]!.value_date),description:`Remboursement client du paiement ${payment.payment_number}`,reference:`REM-${created.insertId}`,sourceType:'PAYMENT_REFUND',sourceId:String(created.insertId),eventType:'REFUNDED',createdBy:r.user!.sub},paymentId),updated=await recalc(c,String(invoice.id));await audit(c,r,'payment_refund',String(created.insertId),'created',{paymentId,invoiceId:String(invoice.id),creditNoteId,amount,reason,idempotencyKey:key,treasuryMovementId:treasury.movementId});return{id:String(created.insertId),invoiceId:String(invoice.id),agencyId:String(invoice.agency_id),duplicate:false,treasuryAgencies:treasury.agencyIds,...updated}});if(!result.duplicate){emitToAgency(result.agencyId,'billing:payment-refunded',{paymentId,refundId:result.id,...result});emitAutomaticMovement(result.treasuryAgencies,{sourceType:'PAYMENT_REFUND',sourceId:result.id})}await requireBusinessArchive(`payment-refund:${result.id}:finalized`,()=>archivePaymentRefund(result.id,r.user!.sub));res.status(result.duplicate?200:201).json(result)}));

billingRouter.get('/invoices/:id/pdf',requirePermission('billing.invoice.view'),asyncHandler(async(r,res)=>{const invoice=await access(id(r.params.id),r,'billing.invoice.view'),buffer=invoice.status==='draft'?await renderInvoiceDocument(String(invoice.id)):await requiredHistoricalBusinessPdf(`invoice:${invoice.id}:issued:v2`,`invoice:${invoice.id}:issued:`);sendPdf(res,buffer,`facture-${invoice.invoice_number}.pdf`)}));
billingRouter.get('/payments/:id/receipt',requirePermission('billing.payment.view'),asyncHandler(async(r,res)=>{const rows=await query<RowDataPacket[]>(`SELECT p.*,pm.name payment_method,i.invoice_number,i.agency_id,i.currency_code,a.name agency_name,COALESCE(c.company_name,CONCAT_WS(' ',c.first_name,c.last_name)) customer_name,CONCAT_WS(' ',u.first_name,u.last_name) received_by_name FROM payments p JOIN invoices i ON i.id=p.invoice_id JOIN agencies a ON a.id=i.agency_id JOIN customers c ON c.id=p.customer_id JOIN payment_methods pm ON pm.id=p.payment_method_id LEFT JOIN users u ON u.id=p.received_by WHERE p.id=?`,[id(r.params.id)]);if(!rows[0])throw new HttpError(404,'Paiement introuvable');const p=rows[0];await access(String(p.invoice_id),r,'billing.payment.view');const buffer=await requiredHistoricalBusinessPdf(`payment:${p.id}:confirmed:v1`,`payment:${p.id}:confirmed:`);sendPdf(res,buffer,`recu-${p.payment_number}.pdf`)}));
billingRouter.get('/credit-notes/:id/pdf',requirePermission('billing.invoice.view'),asyncHandler(async(r,res)=>{const[credit]=await query<RowDataPacket[]>('SELECT id,invoice_id,credit_note_number,status FROM credit_notes WHERE id=?',[id(r.params.id)]);if(!credit)throw new HttpError(404,'Avoir introuvable');await access(String(credit.invoice_id),r,'billing.invoice.view');if(!['issued','applied'].includes(String(credit.status)))throw new HttpError(409,'Avoir officiel indisponible');const buffer=await requiredHistoricalBusinessPdf(`credit-note:${credit.id}:issued:v1`,`credit-note:${credit.id}:issued:`);sendPdf(res,buffer,`avoir-${credit.credit_note_number}.pdf`)}));
billingRouter.post('/payments/:id/cancel',requirePermission('billing.payment.cancel'),asyncHandler(async(r,res)=>{const paymentId=id(r.params.id),reason=txt(r.body.reason,500),key=txt(r.body.idempotencyKey,120);if(!reason||!key)throw new HttpError(400,'Motif et clé d’idempotence requis');const[target]=await query<RowDataPacket[]>('SELECT invoice_id FROM payments WHERE id=?',[paymentId]);if(!target)throw new HttpError(404,'Règlement introuvable');await access(String(target.invoice_id),r,'billing.payment.cancel');const result=await billingTransaction(r,'billing.payment.cancel',async c=>{const invoice=await access(String(target.invoice_id),r,'billing.payment.cancel',c,true),[duplicates]=await c.execute<RowDataPacket[]>('SELECT * FROM payment_cancellations WHERE idempotency_key=? OR payment_id=? FOR UPDATE',[key,paymentId]);if(duplicates[0]){if(String(duplicates[0].payment_id)!==paymentId)throw new HttpError(409,"Cette clé d’idempotence appartient à une autre annulation");return{id:String(duplicates[0].id),invoiceId:String(invoice.id),agencyId:String(invoice.agency_id),duplicate:true,treasuryAgencies:[]as string[]}}const[payments]=await c.execute<RowDataPacket[]>('SELECT * FROM payments WHERE id=? FOR UPDATE',[paymentId]),payment=payments[0];if(!payment||String(payment.invoice_id)!==String(invoice.id)||payment.status!=='confirmed')throw new HttpError(409,'Règlement non annulable');const[refunds]=await c.execute<RowDataPacket[]>('SELECT id FROM payment_refunds WHERE payment_id=? LIMIT 1 FOR UPDATE',[paymentId]);if(refunds[0])throw new HttpError(409,'Un règlement déjà remboursé ne peut pas être annulé');const[movements]=await c.execute<RowDataPacket[]>("SELECT tm.id,EXISTS(SELECT 1 FROM bank_reconciliation_allocations bra JOIN bank_reconciliation_groups brg ON brg.id=bra.group_id WHERE bra.treasury_movement_id=tm.id AND bra.status='ACTIVE' AND brg.status='CONFIRMED') reconciled FROM treasury_movements tm WHERE tm.source_type='PAYMENT' AND tm.source_id=? AND tm.event_type='CONFIRMED' FOR UPDATE",[paymentId]),movement=movements[0];if(!movement)throw new HttpError(409,'Mouvement financier originel introuvable');if(movement.reconciled)throw new HttpError(409,'Le règlement est rapproché et ne peut pas être annulé directement');const[created]=await c.execute<ResultSetHeader>('INSERT INTO payment_cancellations(payment_id,invoice_id,reason,idempotency_key,cancelled_by) VALUES(?,?,?,?,?)',[paymentId,invoice.id,reason,key,r.user!.sub]),treasury=await postPaymentCancellationMovement(c,{agencyId:String(invoice.agency_id),paymentId,cancellationId:String(created.insertId),amount:Number(payment.amount),currencyCode:String(invoice.currency_code),valueDate:new Date().toISOString().slice(0,10),paymentMethodId:String(payment.payment_method_id),reference:String(payment.payment_number),createdBy:r.user!.sub}),updated=await recalc(c,String(invoice.id));await audit(c,r,'payment_cancellation',String(created.insertId),'created',{paymentId,reason,treasuryAccountId:treasury.accountId,treasuryMovementId:treasury.movementId});return{id:String(created.insertId),invoiceId:String(invoice.id),agencyId:String(invoice.agency_id),duplicate:false,treasuryAgencies:treasury.agencyIds,...updated}});if(!result.duplicate){emitToAgency(result.agencyId,'billing:payment-cancelled',{paymentId,...result});emitAutomaticMovement(result.treasuryAgencies,{sourceType:'PAYMENT_CANCELLATION',sourceId:result.id})}await requireBusinessArchive(`cancellation:payment:${paymentId}`,()=>archiveCancellation('payment',paymentId,r.user!.sub));res.status(result.duplicate?200:201).json(result)}));

billingRouter.post('/invoices/:id/payment-attachments',requirePermission('billing.payment.collect'),documentMultipart,asyncHandler(async(r:MultipartRequest,res)=>{const invoiceId=id(r.params.id),invoice=await access(invoiceId,r,'billing.payment.collect'),file=r.documentFile;if(!file)throw new HttpError(400,'Fichier justificatif obligatoire');validateDocumentFile(file);const references=await query<RowDataPacket[]>("SELECT c.id category_id,t.id type_id,t.name type_name FROM document_categories c JOIN document_types t ON t.category_id=c.id WHERE c.code='FINANCIAL_SUPPORTING' AND t.code='PAYMENT_SUPPORTING' AND c.is_active=TRUE AND t.is_active=TRUE"),reference=references[0];if(!reference)throw new HttpError(409,'Référentiel GED des justificatifs de règlement non configuré');const stored=await storeDocument(file,String(invoice.agency_id));try{const result=await billingTransaction(r,'billing.payment.collect',async c=>{const current=await access(invoiceId,r,'billing.payment.collect',c,true),hash=documentHash(file.buffer),[duplicate]=await c.execute<RowDataPacket[]>("SELECT id FROM documents WHERE file_hash=? AND entity_type='invoice' AND entity_id=? AND is_archived=FALSE LIMIT 1 FOR UPDATE",[hash,invoiceId]);if(duplicate[0])return{id:String(duplicate[0].id),duplicate:true};const[created]=await c.execute<ResultSetHeader>("INSERT INTO documents(uploaded_by,origin,title,category_id,document_type,document_type_id,document_date,description,file_name,file_url,mime_type,file_size,version,entity_type,entity_id,agency_id,concession_id,is_archived,file_hash) SELECT ?,'manual',?,?,?,?,CURDATE(),?,?,?,?,?,1,'invoice',?,a.id,a.concession_id,FALSE,? FROM agencies a WHERE a.id=?",[r.user!.sub,`Justificatif de règlement — ${current.invoice_number}`,reference.category_id,reference.type_name,reference.type_id,'Justificatif externe téléversé pendant l’encaissement',file.originalName,`ged:${stored.storageKey}`,file.mimeType,file.buffer.length,invoiceId,hash,current.agency_id]);await audit(c,r,'document',String(created.insertId),'payment_attachment.staged',{invoiceId,fileName:file.originalName,fileHash:hash});return{id:String(created.insertId),duplicate:false}});if(result.duplicate)await unlink(stored.absolute).catch(()=>undefined);res.status(result.duplicate?200:201).json({...result,fileName:file.originalName,mimeType:file.mimeType})}catch(error){await unlink(stored.absolute).catch(()=>undefined);throw error}}));

billingRouter.post('/payments/:id/attachment',requirePermission('billing.payment.collect'),asyncHandler(async(r,res)=>{const paymentId=id(r.params.id),documentId=id(r.body.documentId),result=await billingTransaction(r,'billing.payment.collect',async c=>{const[payments]=await c.execute<RowDataPacket[]>('SELECT p.id,p.invoice_id,p.attachment_document_id,i.agency_id FROM payments p JOIN invoices i ON i.id=p.invoice_id WHERE p.id=? FOR UPDATE',[paymentId]),payment=payments[0];if(!payment)throw new HttpError(404,'Règlement introuvable');await access(String(payment.invoice_id),r,'billing.payment.collect',c,true);if(payment.attachment_document_id!=null){if(String(payment.attachment_document_id)!==documentId)throw new HttpError(409,'Ce règlement possède déjà un autre justificatif');return{paymentId,documentId,duplicate:true}}const[documents]=await c.execute<RowDataPacket[]>("SELECT id FROM documents WHERE id=? AND entity_type='invoice' AND entity_id=? AND agency_id=? AND uploaded_by=? AND is_archived=FALSE FOR UPDATE",[documentId,payment.invoice_id,payment.agency_id,r.user!.sub]);if(!documents[0])throw new HttpError(409,'Justificatif absent, archivé ou hors périmètre');await c.execute("UPDATE documents SET entity_type='payment',entity_id=? WHERE id=?",[paymentId,documentId]);await c.execute('UPDATE payments SET attachment_document_id=? WHERE id=?',[documentId,paymentId]);await audit(c,r,'payment',paymentId,'payment_attachment.attached',{documentId});return{paymentId,documentId,duplicate:false}});res.status(result.duplicate?200:201).json(result)}));

billingRouter.get('/payments/:id/attachment',requirePermission('billing.payment.view'),asyncHandler(async(r,res)=>{const paymentId=id(r.params.id),rows=await query<RowDataPacket[]>(`SELECT p.invoice_id,d.file_name,d.file_url,d.file_hash,d.mime_type FROM payments p JOIN documents d ON d.id=p.attachment_document_id AND d.entity_type='payment' AND d.entity_id=p.id AND d.is_archived=FALSE WHERE p.id=?`,[paymentId]),row=rows[0];if(!row)throw new HttpError(404,'Justificatif de règlement introuvable');await access(String(row.invoice_id),r,'billing.payment.view');const buffer=await readDocumentFile(row.file_url,row.file_hash),mime=verifiedPreviewMime(buffer,row.mime_type);res.setHeader('Content-Type',mime);res.setHeader('Content-Disposition',`inline; filename="${String(row.file_name).replace(/["\r\n]/g,'_')}"`);res.send(buffer)}));

function sendPdf(res:Response,buffer:Buffer,name:string){res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`inline; filename="${name}"`);res.end(buffer)}
